                seqs[m] = seq
                cand = canonical(seqs)
                if cand == cur:
                    continue
                if not base_ok or _acyclic(inst, cand):
                    cur = cand
                    break
        if cur == orig:
            cur = _fallback(inst, orig, rng)
        return cur


